window.PNM_FONT_REG="";
window.PNM_FONT_BOLD="";

/* ===== PoródNaMiarę.pl — generator PDF planu porodu (jsPDF) ===== */
(function(){
  'use strict';
  var W=210, H=297;
  var PNM_LOGO_PNG='data:image/png;base64,';
  var PNM_LOGO_AR=1.0;

  function theme(g){
    return g==='boy'
      ? {ac:[62,126,118], soft:[228,242,240]}
      : {ac:[160,82,94],  soft:[247,233,231]};
  }
  var DEEP=[62,56,82], INK=[58,51,65], SAND=[250,245,239], SD=[237,223,211], GREY=[138,131,145];

  function heart(d,x,y,s,col){
    d.setFillColor(col[0],col[1],col[2]);
    d.lines([[-s,-0.75*s,-s,-1.6*s,0,-1.15*s],[s,-0.45*s,s,0.6*s,0,1.15*s]], x, y+0.55*s, [1,1], 'F', true);
  }

  function Doc(g){
    var t=theme(g);
    var d=new window.jspdf.jsPDF({unit:'mm',format:'a4',compress:true});
    d.addFileToVFS('Lato-R.ttf', window.PNM_FONT_REG);
    d.addFont('Lato-R.ttf','Lato','normal');
    d.addFileToVFS('Lato-B.ttf', window.PNM_FONT_BOLD);
    d.addFont('Lato-B.ttf','Lato','bold');
    d.setFont('Lato','normal');
    return {d:d, t:t, page:0, y:0};
  }

  function pdfLabel(lang, key, fallback){
    try{
      if(lang && lang!=='pl' && window.PNM_I18N && window.PNM_I18N.pdf[lang]) return window.PNM_I18N.pdf[lang][key];
    }catch(e){}
    return fallback;
  }

  function cover(c, dziecko, rodzice, termin){
    var d=c.d, t=c.t, lang=c.lang; c.page=1;
    d.setFillColor(t.soft[0],t.soft[1],t.soft[2]); d.rect(0,0,W,H,'F');
    d.setFillColor(t.ac[0],t.ac[1],t.ac[2]); d.rect(0,0,W,110,'F');
    heart(d, W/2, 32, 7, [255,255,255]);
    d.setTextColor(255,255,255);
    d.setFont('Lato','bold'); d.setFontSize(10);
    d.text(pdfLabel(lang,'cover','PLAN PORODU'), W/2, 62, {align:'center', charSpace:1.2});
    d.setFontSize(dziecko && dziecko.length>12 ? 26 : 32);
    d.text(dziecko||pdfLabel(lang,'parents','Nasze dziecko'), W/2, 80, {align:'center'});
    d.setFont('Lato','normal'); d.setFontSize(12);
    if(rodzice) d.text(rodzice, W/2, 91, {align:'center'});
    if(termin){ d.setFontSize(10); d.text(pdfLabel(lang,'term','Przewidywany termin')+': '+termin, W/2, 100, {align:'center'}); }
    // Logo strony (aktualne, brandowe) — powiększone 3× i wyśrodkowane w pionie oraz poziomie
    var brandY = H-44;
    try{
      var lw=78, lh=lw*PNM_LOGO_AR;             // 78mm = 3× poprzednie 26mm
      var logoTop = 120;                        // tuż pod paskiem (110mm) — środek logo ~53% wysokości strony
      d.addImage(PNM_LOGO_PNG, 'PNG', (W-lw)/2, logoTop, lw, lh, undefined, 'FAST');
      brandY = logoTop + lh + 12;               // adres strony tuż pod logo
    }catch(e){}
    d.setTextColor(t.ac[0],t.ac[1],t.ac[2]);
    d.setFont('Lato','bold'); d.setFontSize(15);
    d.text(pdfLabel(lang,'brand','PorodNaMiare.pl'), W/2, brandY, {align:'center'});
    d.setTextColor(GREY[0],GREY[1],GREY[2]);
    d.setFont('Lato','normal'); d.setFontSize(8);
    d.text(pdfLabel(lang,'standard','Zgodny ze Standardem Opieki Okołoporodowej — Dz.U. 2025 poz. 1525'), W/2, H-33, {align:'center'});
    d.setFontSize(7.5);
    d.text(pdfLabel(lang,'footerNote','Dokument organizacyjny — nie zastępuje porady lekarskiej.'), W/2, H-27, {align:'center', maxWidth:W-40});
  }

  function chrome(c){
    var d=c.d, t=c.t, lang=c.lang;
    d.setFillColor(t.ac[0],t.ac[1],t.ac[2]); d.rect(0,0,W,13,'F');
    d.setTextColor(255,255,255); d.setFont('Lato','bold'); d.setFontSize(9);
    d.text(pdfLabel(lang,'cover','PLAN PORODU'), 16, 8.6);
    d.setFont('Lato','normal'); d.setFontSize(8);
    d.text(pdfLabel(lang,'brand','PorodNaMiare.pl'), W-16, 8.6, {align:'right'});
    d.setFillColor(DEEP[0],DEEP[1],DEEP[2]); d.rect(0,H-9,W,9,'F');
    heart(d, 16, H-6, 1.5, [255,255,255]);
    d.setTextColor(255,255,255); d.setFontSize(7);
    var genLabel = lang==='en'?'Generated at PorodNaMiare.pl':lang==='de'?'Erstellt auf PorodNaMiare.pl':lang==='uk'?'Створено на PorodNaMiare.pl':'Wygenerowano w PorodNaMiare.pl';
    var pageLabel = lang==='en'?'p.':lang==='de'?'S.':lang==='uk'?'стор.':'str.';
    d.text(genLabel, 20, H-5.4);
    d.text(pageLabel+' '+c.page, W-16, H-5.4, {align:'right'});
  }

  function newPage(c){
    if(c.page>0) c.d.addPage();
    c.page++;
    c.d.setFillColor(SAND[0],SAND[1],SAND[2]); c.d.rect(0,0,W,H,'F');
    chrome(c); c.y=22;
  }
  function need(c,h){ if(c.y+h > H-16) newPage(c); }

  function dataBox(c, rows){
    if(!rows.length) return;
    var d=c.d, t=c.t, bh=rows.length*7+7;
    need(c,bh+6);
    d.setFillColor(255,255,255); d.setDrawColor(SD[0],SD[1],SD[2]); d.setLineWidth(0.4);
    d.roundedRect(16,c.y,W-32,bh,3,3,'FD');
    d.setFillColor(t.ac[0],t.ac[1],t.ac[2]); d.roundedRect(16,c.y,2.5,bh,1,1,'F');
    var yy=c.y+8;
    rows.forEach(function(r){
      d.setTextColor(GREY[0],GREY[1],GREY[2]); d.setFont('Lato','normal'); d.setFontSize(7.5);
      d.text(String(r[0]).toUpperCase(), 23, yy);
      d.setTextColor(INK[0],INK[1],INK[2]); d.setFont('Lato','bold'); d.setFontSize(9.5);
      d.text(d.splitTextToSize(String(r[1]), W-96)[0], 72, yy);
      yy+=7;
    });
    c.y+=bh+6;
  }

  function priority(c){
    var d=c.d, t=c.t;
    var txt=pdfLabel(c.lang,'priority','PRIORYTET NADRZĘDNY: zdrowie i życie dziecka oraz matki są bezwzględnym priorytetem, nadrzędnym wobec każdego punktu tego planu. W sytuacji zagrożenia akceptujemy wszystkie niezbędne interwencje medyczne. Prosimy jedynie o możliwie szybką informację o sytuacji.');
    d.setFont('Lato','bold'); d.setFontSize(8.5);
    var lines=d.splitTextToSize(txt, W-48), bh=lines.length*4.4+8;
    need(c,bh+5);
    d.setFillColor(t.soft[0],t.soft[1],t.soft[2]); d.setDrawColor(t.ac[0],t.ac[1],t.ac[2]); d.setLineWidth(0.8);
    d.roundedRect(16,c.y,W-32,bh,3,3,'FD');
    d.setTextColor(DEEP[0],DEEP[1],DEEP[2]);
    var yy=c.y+6.5;
    lines.forEach(function(l){ d.text(l,22,yy); yy+=4.4; });
    c.y+=bh+6;
  }

  function section(c, num, title, items){
    if(!items || !items.length) return;
    var d=c.d, t=c.t;
    need(c,20);
    d.setFillColor(DEEP[0],DEEP[1],DEEP[2]); d.roundedRect(16,c.y,W-32,8.5,2.5,2.5,'F');
    d.setFillColor(t.ac[0],t.ac[1],t.ac[2]); d.circle(22.5,c.y+4.25,3.1,'F');
    d.setTextColor(255,255,255); d.setFont('Lato','bold'); d.setFontSize(8.5);
    d.text(String(num), 22.5, c.y+5.6, {align:'center'});
    d.setFontSize(10.5);
    d.text(d.splitTextToSize(title, W-70)[0], 29, c.y+5.7);
    c.y+=13;
    items.forEach(function(it){
      d.setFont('Lato','normal'); d.setFontSize(9.5);
      var lines=d.splitTextToSize(it, W-50);
      var rh=Math.max(6.8, lines.length*4.5+2.4);
      need(c,rh);
      d.setDrawColor(t.ac[0],t.ac[1],t.ac[2]); d.setFillColor(255,255,255); d.setLineWidth(0.5);
      d.roundedRect(20,c.y-0.4,3.6,3.6,0.7,0.7,'FD');
      d.setLineWidth(0.9);
      d.line(20.8,c.y+1.4,21.7,c.y+2.5); d.line(21.7,c.y+2.5,23,c.y+0.2);
      d.setTextColor(INK[0],INK[1],INK[2]);
      var yy=c.y+2.6;
      lines.forEach(function(l){ d.text(l,26,yy); yy+=4.5; });
      c.y+=rh;
    });
    c.y+=3;
  }

  // Tłumaczenia ramek informacyjnych (PDF) — kanoniczny tekst pozostaje polski w kreatorze,
  // tu tłumaczymy tylko warstwę wyświetlaną, spójnie z resztą planu (EN/DE/UK).
  var PDF_INFO={
    labor:{
      en:['Birth whistle — what it is','A small breathing mouthpiece supporting controlled exhalation in the second stage of labour. It helps keep a steady breathing rhythm and effective pushing without holding the breath.'],
      de:['Geburtspfeife — was das ist','Ein kleines Atem-Mundstück, das die kontrollierte Ausatmung in der Austreibungsphase unterstützt. Es hilft, den Atemrhythmus zu halten und effektiv zu pressen, ohne die Luft anzuhalten.'],
      uk:['Пологовий свисток — що це','Невеликий дихальний мундштук, що підтримує контрольований видих у II періоді пологів. Допомагає тримати ритм дихання та ефективні потуги без затримки повітря.']
    },
    pain:{
      en:['Remifentanil PCA — information','A short-acting opioid delivered by a patient-controlled pump — the mother triggers each dose during a contraction. Rapid onset and offset; requires oxygen-saturation monitoring.'],
      de:['Remifentanil-PCA — Information','Ein kurzwirksames Opioid über eine patientengesteuerte Pumpe — die Gebärende löst jede Dosis während einer Wehe selbst aus. Schneller Wirkeintritt und -abbau; erfordert Sättigungsüberwachung.'],
      uk:['Ремифентаніл PCA — інформація','Короткодіючий опіоїд через помпу з кнопкою — породілля сама вмикає дозу під час перейми. Швидкий початок і кінець дії; потребує моніторингу сатурації.']
    },
    cordblood:{
      en:['Cord blood banking — logistics','Collected from the umbilical vein after cord clamping; non-invasive, also possible during a caesarean. Please note the collection in the records — we notify the courier ourselves.'],
      de:['Nabelschnurblut-Banking — Logistik','Entnahme aus der Nabelvene nach dem Abnabeln; nicht-invasiv, auch beim Kaiserschnitt möglich. Bitte die Entnahme dokumentieren — den Kurier benachrichtigen wir selbst.'],
      uk:['Банкування пуповинної крові — логістика','Забір із пуповинної вени після перетискання; неінвазивний, можливий і при кесаревому розтині. Просимо відзначити забір у документації — курʼєра сповіщаємо самі.']
    },
    nicu:{
      en:['Neonatal care — our priorities','Please treat the points above as the parents\u2019 priorities if the baby needs specialist care. We understand clinical decisions rest with the team — we only ask to be informed and for the earliest possible contact with the baby.'],
      de:['Neonatologische Betreuung — unsere Prioritäten','Bitte betrachten Sie die obigen Punkte als Prioritäten der Eltern, falls das Kind spezialisierte Betreuung braucht. Klinische Entscheidungen liegen beim Team — wir bitten nur um Information und möglichst frühen Kontakt zum Kind.'],
      uk:['Неонатальна допомога — наші пріоритети','Просимо вважати наведені пункти пріоритетами батьків, якщо дитина потребує спеціалізованої допомоги. Клінічні рішення — за командою; просимо лише інформувати нас і про якнайшвидший контакт з дитиною.']
    },
    postpartum:{
      en:['Family room — rationale','The father\u2019s constant presence in the first days supports bonding, helps breastfeeding and relieves the mother. Please let us know about availability and the cost of the hotel service.'],
      de:['Familienzimmer — Begründung','Die ständige Anwesenheit des Vaters in den ersten Tagen stärkt die Bindung, erleichtert das Stillen und entlastet die Mutter. Bitte informieren Sie uns über Verfügbarkeit und Kosten des Hotelservice.'],
      uk:['Сімейна палата — обґрунтування','Постійна присутність батька в перші дні зміцнює звʼязок, полегшує лактацію і розвантажує маму. Просимо повідомити про наявність і вартість готельної послуги.']
    }
  };
  function infoBox(c, title, txt, key, lang){
    var d=c.d, t=c.t;
    if(lang && lang!=='pl' && key && PDF_INFO[key] && PDF_INFO[key][lang]){
      title = PDF_INFO[key][lang][0]; txt = PDF_INFO[key][lang][1];
    }
    d.setFont('Lato','normal'); d.setFontSize(8.5);
    var lines=d.splitTextToSize(txt, W-48), bh=lines.length*4.2+11;
    need(c,bh+5);
    d.setFillColor(255,255,255); d.setDrawColor(t.ac[0],t.ac[1],t.ac[2]); d.setLineWidth(0.5);
    d.roundedRect(16,c.y,W-32,bh,3,3,'FD');
    heart(d,22,c.y+5,2,t.ac);
    d.setTextColor(DEEP[0],DEEP[1],DEEP[2]); d.setFont('Lato','bold'); d.setFontSize(9);
    d.text(title,26,c.y+7);
    d.setTextColor(INK[0],INK[1],INK[2]); d.setFont('Lato','normal'); d.setFontSize(8.5);
    var yy=c.y+12;
    lines.forEach(function(l){ d.text(l,22,yy); yy+=4.2; });
    c.y+=bh+6;
  }

  function signatures(c){
    var d=c.d, lang=c.lang;
    need(c,52);
    d.setTextColor(DEEP[0],DEEP[1],DEEP[2]); d.setFont('Lato','bold'); d.setFontSize(11);
    d.text(pdfLabel(lang,'signTitle','Oświadczenie i podpisy'),16,c.y); c.y+=7;
    d.setFont('Lato','normal'); d.setFontSize(9); d.setTextColor(INK[0],INK[1],INK[2]);
    d.splitTextToSize(pdfLabel(lang,'signText','Świadomie wyrażamy powyższe preferencje. Akceptujemy wszelkie niezbędne interwencje ratujące zdrowie i życie dziecka oraz matki.'), W-32)
      .forEach(function(l){ d.text(l,16,c.y); c.y+=4.6; });
    c.y+=13;
    d.setDrawColor(SD[0],SD[1],SD[2]); d.setLineWidth(0.4);
    d.line(24,c.y,88,c.y); d.line(118,c.y,182,c.y);
    c.y+=5;
    d.setTextColor(GREY[0],GREY[1],GREY[2]); d.setFontSize(8);
    d.text(pdfLabel(lang,'signMother','Matka'),56,c.y,{align:'center'});
    d.text(pdfLabel(lang,'signFather','Ojciec / osoba towarzysząca'),150,c.y,{align:'center'});
    c.y+=10;
    d.setTextColor(INK[0],INK[1],INK[2]); d.setFontSize(9);
    d.text(pdfLabel(lang,'signDate','Data')+': ............................................',16,c.y);
  }

  window.PNM_buildPlanPDF = function(data, lang){
    // Bramka: pełny PDF generujemy wyłącznie po odblokowaniu zakupu.
    // Nie eliminuje to obejścia przez zaawansowanego użytkownika (kod działa w przeglądarce),
    // ale zamyka najprostszą ścieżkę wywołania generatora z konsoli bez płatności.
    var _unlocked = (typeof window.PNM_isUnlocked === 'function') ? window.PNM_isUnlocked() : (window.__freshUnlock === true);
    if(!_unlocked){
      try{ console.warn('[PoródNaMiarę] Pobranie planu dostępne po zakupie pakietu.'); }catch(e){}
      throw new Error('locked');
    }
    lang = lang || 'pl';
    var c=Doc(data.gender);
    c.lang = lang;
    var tr = function(s){
      try{ return (lang!=='pl' && window.PNM_I18N) ? window.PNM_I18N.t(s, lang) : s; }catch(e){ return s; }
    };
    cover(c, data.dziecko, data.rodzice, data.termin);
    newPage(c);
    dataBox(c, (data.rows||[]).map(function(r){
      var label = (lang!=='pl' && window.PNM_I18N && window.PNM_I18N.rowLabels[lang] && window.PNM_I18N.rowLabels[lang][r[0]]) ? window.PNM_I18N.rowLabels[lang][r[0]] : r[0];
      return [label, r[1]];
    }));
    priority(c);
    var n=1;
    (data.sections||[]).forEach(function(s){
      if(s.items && s.items.length){
        var title = lang!=='pl' ? translateStepTitle(s.title, lang) : s.title;
        section(c, n++, title, s.items.map(tr));
        if(s.info) infoBox(c, s.info[0], s.info[1], s.info[2], lang);
      }
    });
    signatures(c);
    return c.d;
  };

  // Mapuje polski tytuł kroku kreatora na jego tłumaczenie (po indeksie w PNM_I18N.steps.pl)
  function translateStepTitle(plTitle, lang){
    try{
      var steps = window.PNM_I18N.steps;
      var idx = steps.pl.indexOf(plTitle);
      if(idx>-1 && steps[lang] && steps[lang][idx]) return steps[lang][idx];
    }catch(e){}
    return plTitle;
  }
})();
